mapper.select:
SELECT /*selectMasterMpRqDssSellerSelList1*/ ROWNUM AS RANK, X.COM_NAME_LOC AS AGENT_NAME, X.ITEM_AMT, X.AGENT_AMT, X.COM_CODE AS AGENT, X.SG_ID, DECODE(X.ITM_MK1,'','',X.ITM_MK1) || DECODE(X.ITM_MK2,'','',DECODE(X.ITM_MK1,'',X.ITM_MK2,', ' || X.ITM_MK2)) || DECODE(X.AGENCY_REMARK,'','',CASE WHEN X.ITM_MK1 IS NULL AND X.ITM_MK2 IS NULL THEN X.AGENCY_REMARK ELSE ' // ' || X.AGENCY_REMARK END) AS REF_MAKER, X.AVL_FLAG, X.CREATE_DATE , f_get_dss_chk(#{st_buyer_code},X.COM_CODE,0) AS DSS_YN , f_get_dss_chk(#{st_buyer_code},X.COM_CODE,1) AS DSS_MSG, TYPE_BEFORE_ONE FROM ( SELECT 0 AS K_RANK, B.COM_CODE, B.COM_NAME_LOC, 0 ITEM_AMT, A.SG_ID, 0 AGENT_AMT, (SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='M104' AND CODE = ITM_MK1) FROM SUPLINFO2 WHERE SUPPLIER = B.COM_CODE) AS ITM_MK1, (SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='M104' AND CODE = ITM_MK2) FROM SUPLINFO2 WHERE SUPPLIER = B.COM_CODE) AS ITM_MK2, (SELECT AGENCY_REMARK FROM SUPLINFO2 WHERE SUPPLIER = B.COM_CODE) AS AGENCY_REMARK, B.AVL_FLAG, TO_CHAR(A.CREATE_DATE,'YYYY/MM/DD') AS CREATE_DATE, (SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M202' AND CODE = TYPE_BEFORE_ONE) FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS TYPE_BEFORE_ONE FROM DSS_S_BUYER_RESULT A, ICOMCMPY B WHERE A.BUYER = #{st_buyer_code} AND A.AGENT = B.COM_CODE AND B.STATUS != 'D' AND A.SG_ID = #{st_sg_id} AND A.STATUS = 'C' AND A.APPROVAL_FLAG = 'Y' AND A.MAKER_CODE IN
#{item}
UNION ALL SELECT 0 AS K_RANK, A.COM_CODE, A.COM_NAME_LOC, 0 ITEM_AMT, #{st_sg_id}, 0 AGENT_AMT, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='M104' AND CODE = B.ITM_MK1) AS ITM_MK1, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='M104' AND CODE = B.ITM_MK2) AS ITM_MK2, B.AGENCY_REMARK AS AGENCY_REMARK, A.AVL_FLAG, TO_CHAR(A.AVL_CREATE_DATE,'YYYY/MM/DD') AS CREATE_DATE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M202' AND CODE = TYPE_BEFORE_ONE) AS TYPE_BEFORE_ONE FROM ICOMCMPY A, SUPLINFO2 B WHERE A.AVL_FLAG = 'Y' AND A.COM_CODE = B.SUPPLIER AND A.STATUS IN ('C','R') AND A.BUSINESS_COND ='S' AND NVL(A.AG_ID,' ') = (SELECT NVL(AG_ID,' ') FROM ICOMCMPY WHERE COM_CODE = #{st_buyer_code}) AND ( B.ITMG1_CD = #{st_sg_id} OR B.ITMG2_CD = #{st_sg_id} OR B.ITMG3_CD = #{st_sg_id} OR B.ITMG4_CD = #{st_sg_id} OR B.ITMG5_CD = #{st_sg_id} ) )X ORDER BY X.AVL_FLAG DESC, X.CREATE_DATE

SELECT /*selectMasterMpRqDssSellerSelList3*/ RANK() OVER (PARTITION BY SG_ID ORDER BY AGNET_AMT DESC) AS RANK , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = AGENT) AS AGENT_NAME , AGNET_AMT AS ITEM_AMT , AGNET_AMT , AGENT , SG_ID , DECODE(ITM_MK1,'','',ITM_MK1) || DECODE(ITM_MK2,'','',DECODE(ITM_MK1,'',ITM_MK2,', ' || ITM_MK2)) || DECODE(AGENCY_REMARK,'','',CASE WHEN ITM_MK1 IS NULL AND ITM_MK2 IS NULL THEN AGENCY_REMARK ELSE ' // ' || AGENCY_REMARK END) AS REF_MAKER, null as AVL_FLAG , null as CREATE_DATE , f_get_dss_chk(#{st_buyer_code},AGENT,0) AS DSS_YN , f_get_dss_chk(#{st_buyer_code},AGENT,1) AS DSS_MSG , TYPE_BEFORE_ONE FROM (SELECT AGENT , SG_ID , SUM(ITEM_AMT) AS AGNET_AMT , (SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='M104' AND CODE = ITM_MK1) FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS ITM_MK1 , (SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='M104' AND CODE = ITM_MK2) FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS ITM_MK2 , (SELECT AGENCY_REMARK FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS AGENCY_REMARK , (SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M202' AND CODE = TYPE_BEFORE_ONE) FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS TYPE_BEFORE_ONE FROM DSS_BUYER_RESULT A WHERE A.BUYER = #{st_buyer_code} AND A.SG_ID = #{st_sg_id} AND A.MAKER_CODE IN
#{item}
AND exists (select 'x' from icomcmpy where com_code = a.agent and status ^= 'D') GROUP BY AGENT,SG_ID )

SELECT /*selectMasterMpRqDssSellerSelList4*/ RANK() OVER (PARTITION BY SG_ID ORDER BY AGNET_AMT DESC) AS RANK , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = AGENT) AS AGENT_NAME , AGNET_AMT AS ITEM_AMT , AGNET_AMT , AGENT , SG_ID , DECODE(ITM_MK1,'','',ITM_MK1) || DECODE(ITM_MK2,'','',DECODE(ITM_MK1,'',ITM_MK2,', ' || ITM_MK2)) || DECODE(AGENCY_REMARK,'','',CASE WHEN ITM_MK1 IS NULL AND ITM_MK2 IS NULL THEN AGENCY_REMARK ELSE ' // ' || AGENCY_REMARK END) AS REF_MAKER, null as AVL_FLAG , null as CREATE_DATE , f_get_dss_chk(#{st_buyer_code},AGENT,0) AS DSS_YN , f_get_dss_chk(#{st_buyer_code},AGENT,1) AS DSS_MSG ,TYPE_BEFORE_ONE FROM (SELECT AGENT , SG_ID , SUM(ITEM_AMT) AS AGNET_AMT , (SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='M104' AND CODE = ITM_MK1) FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS ITM_MK1 , (SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='M104' AND CODE = ITM_MK2) FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS ITM_MK2 , (SELECT AGENCY_REMARK FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS AGENCY_REMARK , (SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M202' AND CODE = TYPE_BEFORE_ONE) FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS TYPE_BEFORE_ONE FROM DSS_BUYER_RESULT A WHERE BUYER = #{st_buyer_code} AND SG_ID = #{st_sg_id} AND A.AGENT NOT IN (SELECT X.AGENT FROM DSS_BUYER_RESULT X WHERE X.BUYER = #{st_buyer_code} AND X.SG_ID = #{st_sg_id} AND X.MAKER_CODE IN
#{item}
) AND exists (select 'x' from icomcmpy where com_code = a.agent and status ^= 'D') GROUP BY AGENT, SG_ID )

/*selectMasterMpRqDssSellerSelList6*/ SELECT /*+INDEX(A SYS_C0040524) INDEX(C ICOMCMPY_PK)*/ RANK() OVER (PARTITION BY SG_ID ORDER BY AGENT_AMT DESC) AS RANK , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = AGENT ) AS AGENT_NAME , AGENT_AMT AS ITEM_AMT , AGENT_AMT , AGENT , SG_ID , DECODE(ITM_MK1,'','',ITM_MK1) || DECODE(ITM_MK2,'','',DECODE(ITM_MK1,'',ITM_MK2,', ' || ITM_MK2)) || DECODE(AGENCY_REMARK,'','',CASE WHEN ITM_MK1 IS NULL AND ITM_MK2 IS NULL THEN AGENCY_REMARK ELSE ' // ' || AGENCY_REMARK END) AS REF_MAKER, null as AVL_FLAG , null as CREATE_DATE , f_get_dss_chk(#{st_buyer_code},AGENT,0) AS DSS_YN , f_get_dss_chk(#{st_buyer_code},AGENT,1) AS DSS_MSG , TYPE_BEFORE_ONE FROM (SELECT AGENT , A.SG_ID , SUM(ITEM_AMT) AS AGENT_AMT , (SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='M104' AND CODE = ITM_MK1) FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS ITM_MK1 , (SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='M104' AND CODE = ITM_MK2) FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS ITM_MK2 , (SELECT AGENCY_REMARK FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS AGENCY_REMARK , (SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M202' AND CODE = TYPE_BEFORE_ONE) FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS TYPE_BEFORE_ONE FROM DSS_BUYER_RESULT A, ICOMCMPY B, ICOMCMPY C WHERE B.COM_CODE = #{st_buyer_code} AND A.SG_ID = #{st_sg_id} AND B.AG_ID = C.AG_ID AND A.AGENT = C.COM_CODE AND A.AGENT NOT IN (SELECT X.AGENT FROM DSS_BUYER_RESULT X WHERE X.SG_ID = #{st_sg_id} AND X.MAKER_CODE IN
#{item}
) AND B.STATUS != 'D' GROUP BY AGENT, A.SG_ID )

/*selectMasterMpRqDssSellerSelList7*/ SELECT /*+INDEX(A SYS_C0040524)*/ RANK() OVER (PARTITION BY SG_ID ORDER BY AGENT_AMT DESC) AS RANK , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = AGENT) AS AGENT_NAME , AGENT_AMT as ITEM_AMT , AGENT_AMT , AGENT , SG_ID , DECODE(ITM_MK1,'','',ITM_MK1) || DECODE(ITM_MK2,'','',DECODE(ITM_MK1,'',ITM_MK2,', ' || ITM_MK2)) || DECODE(AGENCY_REMARK,'','',CASE WHEN ITM_MK1 IS NULL AND ITM_MK2 IS NULL THEN AGENCY_REMARK ELSE ' // ' || AGENCY_REMARK END) AS REF_MAKER, null as AVL_FLAG , null as CREATE_DATE , f_get_dss_chk(#{st_buyer_code},AGENT,0) AS DSS_YN , f_get_dss_chk(#{st_buyer_code},AGENT,1) AS DSS_MSG , TYPE_BEFORE_ONE FROM (SELECT AGENT , SG_ID , 0 AS ITEM_AMT , SUM(ITEM_AMT) AS AGENT_AMT , (SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='M104' AND CODE = ITM_MK1) FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS ITM_MK1 , (SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='M104' AND CODE = ITM_MK2) FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS ITM_MK2 , (SELECT AGENCY_REMARK FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS AGENCY_REMARK, (SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M202' AND CODE = TYPE_BEFORE_ONE) FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS TYPE_BEFORE_ONE FROM DSS_BUYER_RESULT A WHERE SG_ID = #{st_sg_id} AND MAKER_CODE IN
#{item}
AND exists (select 'x' from icomcmpy where com_code = a.agent and status ^= 'D') GROUP BY AGENT, SG_ID )

SELECT /*selectMasterMpRqDssSellerSelList8*/ RANK() OVER (PARTITION BY SG_ID ORDER BY AGENT_AMT DESC) AS RANK , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = AGENT) AS AGENT_NAME , AGENT_AMT as ITEM_AMT , AGENT_AMT , AGENT , SG_ID , DECODE(ITM_MK1,'','',ITM_MK1) || DECODE(ITM_MK2,'','',DECODE(ITM_MK1,'',ITM_MK2,', ' || ITM_MK2)) || DECODE(AGENCY_REMARK,'','',CASE WHEN ITM_MK1 IS NULL AND ITM_MK2 IS NULL THEN AGENCY_REMARK ELSE ' // ' || AGENCY_REMARK END) AS REF_MAKER, null as AVL_FLAG , null as CREATE_DATE , f_get_dss_chk(#{st_buyer_code},AGENT,0) AS DSS_YN , f_get_dss_chk(#{st_buyer_code},AGENT,1) AS DSS_MSG , TYPE_BEFORE_ONE FROM (SELECT AGENT , SG_ID , 0 AS ITEM_AMT , SUM(ITEM_AMT) AS AGENT_AMT , (SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='M104' AND CODE = ITM_MK1) FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS ITM_MK1 , (SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='M104' AND CODE = ITM_MK2) FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS ITM_MK2 , (SELECT AGENCY_REMARK FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS AGENCY_REMARK , (SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M202' AND CODE = TYPE_BEFORE_ONE) FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS TYPE_BEFORE_ONE FROM DSS_BUYER_RESULT A WHERE SG_ID = #{st_sg_id} AND A.AGENT NOT IN (SELECT X.AGENT FROM DSS_BUYER_RESULT X WHERE X.SG_ID = #{st_sg_id} AND X.MAKER_CODE IN
#{item}
) AND exists (select 'x' from icomcmpy where com_code = a.agent and status ^= 'D') GROUP BY AGENT, SG_ID )

/*selectMasterMpRqDssSellerSelList18*/ SELECT B.COM_CODE AS AGENT ,(SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = B.COM_CODE) AS AGENT_NAME , A.DELY_LEVEL_CODE AS DELY_LEVEL_CODE , (SELECT COD.TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE ='M072'AND COD.CODE = A.DELY_LEVEL_CODE) AS DELY_LEVEL_NAME , A.CREDIT_AMOUNT AS CREDIT_AMOUNT , A.KEP_AMOUNT AS KEP_AMOUNT , A.KEP_AMOUNT AS AGENT_AMT , B.DELY_AREA AS DELY_AREA , F_GET_DSS_CHK(#{st_buyer_code} ,A.AGENT,0) AS DSS_YN , F_GET_DSS_CHK(#{st_buyer_code} ,A.AGENT,1) AS DSS_MSG , (SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M202' AND CODE = TYPE_BEFORE_ONE) FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS TYPE_BEFORE_ONE FROM DSS_SMART_QUOTATION A, ICOMCMPY B WHERE A.AGENT = B.COM_CODE AND A.REP_MAKER_TYPE = 'NO' AND A.REP_MAKER_CODE IN ( SELECT D.TEXT8 FROM ICOMCOD1 C, ICOMCOD1 D WHERE C.TYPE ='M104'AND D.TYPE ='M104'AND C.TEXT8 = D.TEXT8 AND C.CODE in
#{item}
)
UNION ALL
SELECT B.COM_CODE AS AGENT ,(SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = B.COM_CODE) AS AGENT_NAME , A.DELY_LEVEL_CODE AS DELY_LEVEL_CODE , (SELECT COD.TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE ='M072'AND COD.CODE = A.DELY_LEVEL_CODE) AS DELY_LEVEL_NAME , A.CREDIT_AMOUNT AS CREDIT_AMOUNT , A.KEP_AMOUNT AS KEP_AMOUNT , A.KEP_AMOUNT AS AGENT_AMT , B.DELY_AREA AS DELY_AREA , F_GET_DSS_CHK(#{st_buyer_code} ,A.AGENT,0) AS DSS_YN , F_GET_DSS_CHK(#{st_buyer_code} ,A.AGENT,1) AS DSS_MSG , (SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M202' AND CODE = TYPE_BEFORE_ONE) FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT) AS TYPE_BEFORE_ONE FROM DSS_SMART_QUOTATION A, ICOMCMPY B WHERE A.AGENT = B.COM_CODE AND A.REP_MAKER_TYPE = 'SG' AND A.REP_MAKER_CODE IN ( SELECT D.TEXT8 FROM ICOMCOD1 C, ICOMCOD1 D WHERE C.TYPE ='M104'AND D.TYPE ='M104'AND C.TEXT8 = D.TEXT8 AND C.CODE in
#{item}
) AND A.SG_ID IN ( SELECT CATEG.SG_ID FROM CMSCATEG CATEG WHERE CATEG.CMS_CATEG_ID =#{st_cms_categ_id} )
ORDER BY KEP_AMOUNT DESC

/*master.mprq.selectMasterMpRqDssMisumiCheckoutResult*/
	SELECT 
	       'KRMISU0004G^'||
	       STOA_LIST_PRICE||'^'|| 
	       LEAD_TIME ||'^'|| 
	       CASE WHEN TAX_RATE != 0 THEN '11' ELSE '13' END ||'^'|| 
	       MOQ ||'^'|| 
	       PUR_UNIT_QTY ||'^'|| 
	       F_GET_SELLER_AREA_ALL(A.BUYER) ||'^'||
	       A.SELLER_ITEM_NO
	  FROM MSM_QTDT A
	 WHERE A.BUYER = #{st_buyer_code}
	   AND A.QUOTATION_NO = #{st_quotation_no}
	   AND A.QUOTATION_SEQ = #{st_quotation_seq}
	   AND A.REVISION = #{st_revision}
	   AND A.RFQ_KEP_USER = #{st_user_id}
